/**
 * 使用TAF-JCE数据格式作为RPC协议的客户端协议解析器
 */
var Taf = require("@taf/taf-stream");
var TafPacket = require("./BasePacketFJce.js").taf;

var stream = function () {
    this._name = "taf";

    this._version = 1;
}

stream.prototype.__defineGetter__("name", function () {
    return this._name;
});

module.exports = stream;

/**
 * 根据传入数据进行打包的方法
 * @param request
 * request.iRequestId : 框架生成的请求序列号
 * request.sFuncName  : 函数名称
 * request.sBuffer    : 函数传入的打包数据
 */
stream.prototype.compose = function ($protoMessage) {
    var option = {};
    var packetType = 0,
        iVersion = 1;
    if ($protoMessage && $protoMessage.property) {
        option = $protoMessage.property;
        if (option) {
            if (option.packetType && option.packetType === 1) {
                packetType = 1;
            }
            if (option.iVersion) {
                iVersion = option.iVersion;
            }
        }
    }

    var req = new TafPacket.BasePacket();
    req.iVersion        = iVersion;
    req.cPacketType     = packetType;
    req.iMessageType    = 0;
    req.iTimeout        = $protoMessage.iTimeout || 0;
    req.iRequestId      = $protoMessage.iRequestId;
    req.sServantName    = $protoMessage.sServantName;
    req.sFuncName       = $protoMessage.sFuncName;
    req.sBuffer         = $protoMessage.sBuffer;

    //设置染色以及context等属性
    if ($protoMessage.property && $protoMessage.property.dyeing && $protoMessage.property.dyeing.dyeing) {
        req.iMessageType = req.iMessageType | 0x04;
        req.status.insert("SDK", ($protoMessage.property.dyeing.key || '').toString());
    }
    if ($protoMessage.property && $protoMessage.property.tracing) {
        req.iMessageType = req.iMessageType | 0x80;
        req.status.insert("STK", $protoMessage.property.tracing);
    }
    if ($protoMessage.property && $protoMessage.property.context) {
        // 修复context 不能传递的问题Map的问题，不支持传递json对象
        $protoMessage.property.context.forEach &&
        $protoMessage.property.context.forEach(function (key, value) {
            req.context.insert(key, value);
        })
    }

    //对请求结构体打包
    var os = new Taf.JceOutputStream();
    os.setHeaderLength(0);
    req._writeTo(os);
    os.setHeaderLength(os.getBinBuffer().length);

    return os.getBinBuffer().toNodeBuffer();
}

// /**
//  * 网络收取包之后，填入数据判断是否完整包
//  */
stream.prototype.feed = function (networkBuffer, message) {

    if (networkBuffer.getBufferLength() < 4) {
        return false;
    }
    //有一个完整的包
    var Length = networkBuffer.readLength();

    if (Length > networkBuffer.getBufferLength()) {
        //包没有收全
        return false;
    }

    networkBuffer.moveHeader(4);

    var is = new Taf.JceInputStream(new Taf.BinBuffer(networkBuffer.getBuffers(Length - 4)));

    networkBuffer.moveHeader(Length - 4);

    message.origin = TafPacket.BasePacket._readFrom(is);
    message.iRequestId = message.origin.iRequestId;

    return message;
}
